using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.CostCenters.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.CostCenters.Queries.GetCostCenters;public sealed class GetCostCentersQueryHandler(ICostCenterRepository repository):IRequestHandler<GetCostCentersQuery,Result<IReadOnlyList<CostCenterDto>>>{public async Task<Result<IReadOnlyList<CostCenterDto>>>Handle(GetCostCentersQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<CostCenterDto>>((await repository.GetAllAsync(cancellationToken)).Select(CostCenterDto.FromEntity).ToList());}
